/**
 * TradeWarRoom — "Compared with no transaction" (`analysis.statusQuo`,
 * status_quo_v1, MD-112 Part 9A; docs/ui/BACKEND_API_HANDOFF.md).
 *
 * Fixtures are REAL `POST /api/trade/analyze` output (generated by the backend
 * harness, never edited here).  Display only: the backend's own sentence,
 * which option is preferred (`preferred: null` reads as not enough evidence,
 * never as either answer), and each component's margin in its own units —
 * inside / outside the band read from `insideBand`, never from a clearance's
 * sign, and the two components never added together.
 */
import { act, fireEvent, render, screen, within } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import TradeWarRoom from "@/components/trade/TradeWarRoom";
import { statusQuoPreferredWords, statusQuoSummary } from "@/lib/trade-war-room-copy";

import CONSOLIDATION from "../fixtures/trade-war-room/consolidation.json";
import FORCED from "../fixtures/trade-war-room/forced-cut.json";
import ASSET_ONLY from "../fixtures/trade-war-room/asset-only.json";
import STRATEGY_CUT_NO from "../fixtures/trade-war-room/strategy-cut-no.json";
import TOO_CLOSE from "../fixtures/trade-war-room/too-close-strategy.json";
import AJ_BROWN from "../fixtures/trade-war-room-mock/aj-brown-herbert.json";

const req = (fixture) => ({ ...(fixture._fixture?.request || {}), mySide: 0 });

function ok(body, status = 200) {
  return { ok: status < 400, status, json: async () => body };
}

async function settle(ms = 800) {
  await act(async () => {
    vi.advanceTimersByTime(ms);
  });
  await act(async () => {});
}

async function renderWith(fixture) {
  globalThis.fetch = vi.fn(async () => ok(fixture));
  const view = render(
    <TradeWarRoom
      request={req(fixture)}
      leagueKey="main"
      useTeamContext={fixture._fixture?.request?.useTeamContext}
    />,
  );
  await settle();
  return view;
}

/** A fixture with its statusQuo replaced (fixtures themselves are never edited). */
function withStatusQuo(fixture, patch) {
  const copy = structuredClone(fixture);
  copy.analysis.statusQuo = patch(copy.analysis.statusQuo);
  return copy;
}

function block() {
  return screen.getByTestId("war-room-status-quo");
}

function componentText(key) {
  return block().querySelector(`[data-component="${key}"]`).textContent;
}

beforeEach(() => {
  vi.useFakeTimers({ shouldAdvanceTime: true });
});

afterEach(() => {
  vi.useRealTimers();
  vi.restoreAllMocks();
});

describe("Compared with no transaction", () => {
  it("renders the backend sentence and each margin in its own units (trade preferred)", async () => {
    await renderWith(CONSOLIDATION);
    const sq = CONSOLIDATION.analysis.statusQuo;
    const region = block();
    expect(
      within(region).getByRole("heading", { name: "Compared with no transaction" }),
    ).toBeTruthy();
    expect(screen.getByTestId("status-quo-text")).toHaveTextContent(sq.text);
    expect(screen.getByTestId("status-quo-preferred")).toHaveTextContent(
      "Better option: Making the trade.",
    );
    // tradeClearance 1190 value points; 0.21 ppg -> 0.2 points per week.
    expect(componentText("objectiveValue")).toBe(
      "Trade value: outside its neutral band of ±250 value points: 1,190 value points past it toward making the trade.",
    );
    expect(componentText("rosterBenefit")).toBe(
      "Weekly lineup: outside its neutral band of ±1.3 points per week: 0.2 points per week past it toward making the trade.",
    );
    expect(region.textContent).toMatch(/the two are never added together/);
    expect(screen.getByTestId("status-quo-opportunity")).toHaveTextContent(
      sq.opportunityCost.text,
    );
  });

  it("never shows a sum of the two components", async () => {
    await renderWith(CONSOLIDATION);
    const m = CONSOLIDATION.analysis.statusQuo.margin;
    const text = block().textContent;
    // value points + points per week is not a quantity: 1,440 + 1.52.
    const sum = m.objectiveValue.value + m.rosterBenefit.value;
    expect(text).not.toContain(Math.round(sum).toLocaleString("en-US"));
    expect(text).not.toContain(sum.toFixed(1));
    expect(text).not.toContain(sum.toLocaleString("en-US"));
  });

  it("names keeping the roster when declining is preferred, each component its own way", async () => {
    await renderWith(STRATEGY_CUT_NO);
    expect(screen.getByTestId("status-quo-text")).toHaveTextContent(
      STRATEGY_CUT_NO.analysis.statusQuo.text,
    );
    expect(screen.getByTestId("status-quo-preferred")).toHaveTextContent(
      "Better option: Keeping your current roster.",
    );
    // value -1426 opposes: statusQuoClearance 1090.9 -> 1,091.
    expect(componentText("objectiveValue")).toBe(
      "Trade value: outside its neutral band of ±335 value points: 1,091 value points past it toward keeping your current roster.",
    );
    // 6.88 ppg favours the trade: tradeClearance 5.71 -> 5.7.
    expect(componentText("rosterBenefit")).toBe(
      "Weekly lineup: outside its neutral band of ±1.2 points per week: 5.7 points per week past it toward making the trade.",
    );
  });

  it("a component inside its band favours neither option, with no clearance shown", async () => {
    await renderWith(TOO_CLOSE);
    const text = componentText("objectiveValue");
    expect(text).toBe(
      "Trade value: inside its neutral band of ±250 value points (net +50 value points), so it favours neither option.",
    );
    expect(text).not.toMatch(/200|300/);
  });

  it("insideBand decides, never the clearance's sign", async () => {
    const fixture = withStatusQuo(TOO_CLOSE, (sq) => ({
      ...sq,
      margin: {
        ...sq.margin,
        // A hair inside the band: the rounded clearance reads 0.0.
        objectiveValue: {
          ...sq.margin.objectiveValue,
          value: 249.96,
          tradeClearance: 0.0,
          statusQuoClearance: -500,
          direction: "neutral",
          insideBand: true,
        },
        // A hair outside: also 0.0, but outside.
        rosterBenefit: {
          ...sq.margin.rosterBenefit,
          value: 1.001,
          neutralBandHalfWidth: 1,
          tradeClearance: 0.0,
          statusQuoClearance: -2,
          direction: "favors",
          insideBand: false,
        },
      },
    }));
    await renderWith(fixture);
    expect(componentText("objectiveValue")).toMatch(
      /inside its neutral band .* favours neither option/,
    );
    expect(componentText("rosterBenefit")).toBe(
      "Weekly lineup: outside its neutral band of ±1.0 points per week: just past it toward making the trade.",
    );
  });

  it("insufficient evidence reads as not enough evidence — never as either answer, never 0", async () => {
    await renderWith(FORCED);
    expect(FORCED.analysis.statusQuo.preferred).toBeNull();
    const preferred = screen.getByTestId("status-quo-preferred");
    expect(preferred).toHaveTextContent("Better option: Not enough evidence to say either way.");
    expect(preferred.textContent).not.toMatch(/Keeping|Making/);
    for (const key of ["objectiveValue", "rosterBenefit"]) {
      expect(componentText(key)).toMatch(
        /not evaluated — not enough evidence \(unknown, not zero\)\./,
      );
    }
    // No number at all is invented for a component that was not evaluated.
    expect(block().querySelector("ul").textContent).not.toMatch(/\d/);
  });

  it("an absent preferred field is also not enough evidence", () => {
    expect(statusQuoPreferredWords(undefined)).toBe("Not enough evidence to say either way");
    expect(statusQuoPreferredWords(null)).toBe("Not enough evidence to say either way");
    expect(statusQuoSummary({ text: "x" }).insufficient).toBe(true);
  });

  it("asset-only: the lineup part is excluded by mode, not missing", async () => {
    await renderWith(ASSET_ONLY);
    expect(componentText("rosterBenefit")).toBe(
      "Weekly lineup: not part of an asset-only analysis.",
    );
  });

  it("opportunity cost is shown only when the backend marks it unavailable with words", async () => {
    const fixture = withStatusQuo(CONSOLIDATION, (sq) => ({
      ...sq,
      opportunityCost: { ...sq.opportunityCost, state: "evaluated" },
    }));
    await renderWith(fixture);
    expect(screen.queryByTestId("status-quo-opportunity")).toBeNull();
  });

  it("renders nothing when the packet carries no statusQuo", async () => {
    expect(AJ_BROWN.analysis.statusQuo).toBeUndefined();
    await renderWith(AJ_BROWN);
    expect(screen.getByTestId("decision-headline")).toBeTruthy();
    expect(screen.queryByTestId("war-room-status-quo")).toBeNull();
    expect(statusQuoSummary(undefined)).toBeNull();
    expect(statusQuoSummary(null)).toBeNull();
  });
});

describe("Not included yet — value uncertainty reason", () => {
  it("words the calibrated-band reason, not the generic fallback", async () => {
    const dims = CONSOLIDATION.analysis.unavailableDimensions;
    expect(dims.some((d) => d.reason === "no_empirically_calibrated_band")).toBe(true);
    await renderWith(CONSOLIDATION);
    fireEvent.click(screen.getByRole("button", { name: "Sources, simulations and methodology" }));
    expect(document.body.textContent).toMatch(
      /Value uncertainty ranges\s*—\s*no measured range exists yet: the simulation's spread is an assumed band, not a calibrated one, so it is left out/,
    );
  });

  it("keeps the older unaudited-model wording for payloads that still carry it", async () => {
    expect(AJ_BROWN.analysis.unavailableDimensions[0].reason).toBe("unaudited_model");
    await renderWith(AJ_BROWN);
    fireEvent.click(screen.getByRole("button", { name: "Sources, simulations and methodology" }));
    expect(document.body.textContent).toMatch(
      /Value uncertainty ranges\s*—\s*its model has not passed review yet, so it is left out/,
    );
  });
});
